1	/**
2	 * The cypress-realworld-app Witness calibration driver.
3	 *
4	 * The journey's selectors, routes and backend category were declared from the
5	 * application's own Cypress specs, never yet read off the live DOM+backend.
6	 * Pinning a stateful journey before the live surface has been measured is what
7	 * the TinyTranslator/Super-Productivity rounds spent passes undoing. This drives
8	 * ONE lane of the built production-static output against the application's REAL
9	 * Express-over-lowdb backend — booted through the SAME generic serving path the
10	 * proof uses (`startStaticServer` + `startLiveBackend`), so the origin/CORS
11	 * coordination this driver exercises is the product's, not a bespoke copy — and
12	 * prints every measurement: the ordered steps and their refusals, the recorded
13	 * navigations, every request outcome bucketed by origin, and the tracked-event
14	 * counts.
15	 *
16	 * It publishes nothing, asserts nothing of its own, and is not part of any
17	 * receipt. Its only output is stdout. The backend is booted in the application's
18	 * own era runtime cell (Node 14.16.1), reseeded from its frozen snapshot before
19	 * the pass, exactly as the live-backend serving path reseeds.
20	 */
21	
22	import { readFileSync } from 'node:fs';
23	import { basename, join, resolve } from 'pathe';
24	import { box, runBoxes } from '@async/witness';
25	import { joinURL, parseHost, parseURL, stringifyParsedURL } from 'ufo';
26	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
27	import { WITNESS_REACT_CYPRESS_RWA_ACTOR } from '../../../core/src/receipts/witness-react-cypress-rwa.ts';
28	import { type LiveBackendSpec, startLiveBackend } from '../witness/live-backend.ts';
29	import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
30	import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
31	import type { WitnessObservedRequestOutcome } from '../witness/playwright-host.ts';
32	import { startStaticServer } from '../witness/real-app-run.ts';
33	
34	const root = resolve(import.meta.dirname, '../../../..');
35	const workRoot = join(root, '.versionless/work/react-cypress-rwa');
36	const eraNodeBin = join(
37		root,
38		'.versionless/cache/react-cypress-rwa-runtime/node-v14.16.1-darwin-x64/bin',
39	);
40	const eraYarnBin = join(root, '.versionless/cache/react-cypress-rwa-baseline/npm-global/bin');
41	const chromiumExecutable = join(
42		root,
43		'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
44	);
45	
46	const laneStaticRoot = {
47		baseline: join(workRoot, 'baseline/build-run1'),
48		migrated: join(workRoot, 'target/build-vite-run1'),
49	} as const;
50	
51	/** The application source lane the backend server is spawned from. */
52	const backendLaneRoot = join(workRoot, 'baseline');
53	const BACKEND_PORT = 3001;
54	
55	const VIEWPORT = { width: 1280, height: 900 } as const;
56	
57	/**
58	 * The application's own live-backend declaration, exactly as the AppSpec declares
59	 * it: the app's server command, the loopback host and port its built SPA
60	 * addresses, and the CORS-origin port variable the harness injects the served
61	 * port into. The era-runtime PATH is the one application-specific fact the
62	 * calibration adds — the proof's executeRun path inherits the runtime cell a
63	 * different way — so the serving/origin coordination measured here is the
64	 * generic one.
65	 */
66	const backendSpec: LiveBackendSpec = {
67		command: 'yarn',
68		args: ['start:api'],
69		cwd: '.',
70		port: BACKEND_PORT,
71		host: 'localhost',
72		corsOriginPortEnv: ['REACT_APP_PORT'],
73		env: {
74			PATH: `${eraNodeBin}:${eraYarnBin}:${process.env.PATH ?? ''}`,
75			SKIP_YARN_COREPACK_CHECK: '1',
76		},
77		seed: { snapshot: 'data/database-seed.json', store: 'data/database.json' },
78		prepare: [{ from: 'scripts/mock-aws-exports.js', to: 'src/aws-exports.js' }],
79		health: { path: '/checkAuth', okStatus: [401] },
80		readyTimeoutMs: 45_000,
81	};
82	
83	const firstLine = (error: unknown): string =>
84		(error instanceof Error ? error.message : String(error)).split('\n')[0]!.trim();
85	
86	async function delay(ms: number): Promise<void> {
87		await new Promise<void>((settle) => void setTimeout(settle, ms));
88	}
89	
90	/** Swap the host of a `http://<host>:<port>` origin, keeping the bound port. */
91	function withHost(origin: string, host: string): string {
92		const port = parseHost(parseURL(origin).host ?? '').port ?? '';
93		return stringifyParsedURL({ protocol: 'http:', host: `${host}:${port}` });
94	}
95	
96	function bucketRequests(
97		outcomes: readonly WitnessObservedRequestOutcome[],
98		staticOrigin: string,
99		backendOrigin: string,
100	): unknown {
101		const backend = new Map<string, { count: number; statuses: number[] }>();
102		const other: Array<{ method: string; url: string; status: number | null }> = [];
103		let staticCount = 0;
104		for (const outcome of outcomes) {
105			if (outcome.url.startsWith(staticOrigin)) {
106				staticCount += 1;
107				continue;
108			}
109			if (outcome.url.startsWith(backendOrigin)) {
110				const parsed = parseURL(outcome.url.slice(backendOrigin.length));
111				const path = parsed.pathname || '/';
112				const key = `${outcome.method} ${path}`;
113				const existing = backend.get(key);
114				if (existing === undefined) backend.set(key, { count: 1, statuses: [outcome.status ?? 0] });
115				else {
116					existing.count += 1;
117					if (!existing.statuses.includes(outcome.status ?? 0))
118						existing.statuses.push(outcome.status ?? 0);
119				}
120				continue;
121			}
122			other.push({ method: outcome.method, url: outcome.url, status: outcome.status });
123		}
124		return {
125			staticCount,
126			backend: [...backend.entries()]
127				.map(([key, value]) => ({ endpoint: key, ...value }))
128				.sort((left, right) => left.endpoint.localeCompare(right.endpoint)),
129			other,
130		};
131	}
132	
133	function pageSummary(receiptPath: string): unknown {
134		const receipt = JSON.parse(readFileSync(receiptPath, 'utf8')) as {
135			boxes?: Array<{ pages?: Array<Record<string, unknown>> }>;
136		};
137		const page = receipt.boxes?.[0]?.pages?.[0];
138		if (page === undefined) return null;
139		return {
140			navigations: (page.navigations as Array<{ url: string }> | undefined)?.map((navigation) => {
141				const parsed = parseURL(navigation.url);
142				return `${parsed.pathname}${parsed.hash}`;
143			}),
144			trackedEvents: Object.fromEntries(
145				Object.entries((page.trackedEvents as Record<string, unknown[]>) ?? {}).map(
146					([name, events]) => [name, events.length],
147				),
148			),
149			consoleErrors: (page.consoleMessages as Array<{ level: string }> | undefined)?.filter(
150				(message) => message.level === 'error',
151			).length,
152			pageErrors: (page.pageErrors as unknown[] | undefined)?.length,
153			failedRequests: page.failedRequests,
154		};
155	}
156	
157	export async function calibrateCypressRwaLane(lane: 'baseline' | 'migrated'): Promise<void> {
158		const actor = WITNESS_REACT_CYPRESS_RWA_ACTOR;
159		const staticRoot = laneStaticRoot[lane];
160		const receiptDir = join(root, '.versionless/stage/witness-react-cypress-rwa-calibrate', lane);
161		// The generic serving path: bind the static server first, then boot the backend
162		// with the ephemeral served SPA port injected, and address the browser at the
163		// declared host so the document origin is the one the backend's CORS allow-list
164		// admits.
165		const staticServer = await startStaticServer(staticRoot, { profile: 'current-witness' });
166		const servedOrigin = withHost(staticServer.origin, backendSpec.host ?? '127.0.0.1');
167		const servedPort = Number(parseHost(parseURL(servedOrigin).host ?? '').port ?? '');
168		const backend = await startLiveBackend(backendLaneRoot, backendSpec, { spaPort: servedPort });
169		const host = createPlaywrightWitnessHost({
170			chromiumExecutable,
171			contextProfile: 'current-witness',
172			viewport: VIEWPORT,
173		});
174		const steps: Array<{ name: string; outcome: string }> = [];
175		const probes: Record<string, number | string> = {};
176		let status = 'unknown';
177		let failure = '';
178		let receiptPath = '';
179		const definition = box(`cypress-rwa-calibrate-${lane}`, async (context) => {
180			const page = await context.browser.visit(joinURL(servedOrigin, '/'));
181			await page.trackEvents('click', 'input', 'change', 'keydown', 'mouseover');
182			const step = async (name: string, fn: () => Promise<void>): Promise<void> => {
183				try {
184					await fn();
185					steps.push({ name, outcome: 'ok' });
186				} catch (error: unknown) {
187					steps.push({ name, outcome: `FAIL: ${firstLine(error)}` });
188				}
189				await delay(400);
190			};
191			// Parse the observed count out of a `count(sel, 0)` refusal so a probe never
192			// ends the pass; a genuinely absent selector reports 0.
193			const probe = async (selector: string): Promise<void> => {
194				try {
195					await context.expect.page.count(page, selector, 0);
196					probes[selector] = 0;
197				} catch (error: unknown) {
198					const line = firstLine(error);
199					const match = line.match(/observed (\d+)/);
200					probes[selector] = match ? Number(match[1]) : line;
201				}
202			};
203	
204			await probe('[data-test=signin-username]');
205			await probe('[data-test=signup]');
206			await step('click signup', () => page.click('[data-test=signup]'));
207			await probe('[data-test=signup-first-name]');
208			await step('type signup first', () =>
209				page.type('[data-test=signup-first-name]', actor.firstName, { redact: false }),
210			);
211			await step('type signup last', () =>
212				page.type('[data-test=signup-last-name]', actor.lastName, { redact: false }),
213			);
214			await step('type signup username', () =>
215				page.type('[data-test=signup-username]', actor.username, { redact: false }),
216			);
217			await step('type signup password', () =>
218				page.type('[data-test=signup-password]', actor.password, { redact: false }),
219			);
220			await step('type signup confirm', () =>
221				page.type('[data-test=signup-confirmPassword]', actor.password, { redact: false }),
222			);
223			await step('click signup-submit', () => page.click('[data-test=signup-submit]'));
224			await delay(1_200);
225			await probe('[data-test=signin-username]');
226			await step('type signin username', () =>
227				page.type('[data-test=signin-username]', actor.username, { redact: false }),
228			);
229			await step('type signin password', () =>
230				page.type('[data-test=signin-password]', actor.password, { redact: false }),
231			);
232			await step('click signin-submit', () => page.click('[data-test=signin-submit]'));
233			await delay(1_800);
234			// Onboarding
235			await probe('[data-test=user-onboarding-next]');
236			await probe('[data-test=user-onboarding]');
237			await step('click onboarding-next-1', () =>
238				page.click('[data-test=user-onboarding-next]', { timeoutMs: 6_000 }),
239			);
240			await probe('[data-test=bankaccount-bankName-input]');
241			await step('type bank name', () =>
242				page.type('[data-test=bankaccount-bankName-input]', 'Versionless Bank', { redact: false }),
243			);
244			await step('type routing', () =>
245				page.type('[data-test=bankaccount-routingNumber-input]', '987654321', { redact: false }),
246			);
247			await step('type account', () =>
248				page.type('[data-test=bankaccount-accountNumber-input]', '123456789', { redact: false }),
249			);
250			await step('click bankaccount-submit', () =>
251				page.click('[data-test=bankaccount-submit]', { timeoutMs: 6_000 }),
252			);
253			await delay(1_200);
254			await probe('[data-test=user-onboarding-next]');
255			await step('click onboarding-next-2', () =>
256				page.click('[data-test=user-onboarding-next]', { timeoutMs: 6_000 }),
257			);
258			await delay(1_000);
259			// Settings
260			await probe('[data-test=sidenav-user-settings]');
261			await step('click sidenav-user-settings', () =>
262				page.click('[data-test=sidenav-user-settings]', { timeoutMs: 6_000 }),
263			);
264			await probe('[data-test=user-settings-firstName-input]');
265			await step('type settings first', () =>
266				page.type('[data-test=user-settings-firstName-input]', actor.firstName, {
267					redact: false,
268					clear: true,
269				}),
270			);
271			await step('click user-settings-submit', () =>
272				page.click('[data-test=user-settings-submit]', { timeoutMs: 6_000 }),
273			);
274			await delay(1_000);
275			// Money movement
276			await probe('[data-test=nav-top-new-transaction]');
277			await step('click nav-top-new-transaction', () =>
278				page.click('[data-test=nav-top-new-transaction]', { timeoutMs: 6_000 }),
279			);
280			await probe('[data-test=user-list-search-input]');
281			await step('type search', () =>
282				page.type('[data-test=user-list-search-input]', 'a', { redact: false }),
283			);
284			await delay(1_500);
285			await probe('[data-test^=user-list-item-]');
286			await step('click first user-list-item', () =>
287				page.click('[data-test^=user-list-item-]', { timeoutMs: 6_000 }),
288			);
289			await probe('[data-test=transaction-create-amount-input]');
290			await step('type amount', () =>
291				page.type('[data-test=transaction-create-amount-input]', '15', { redact: false }),
292			);
293			await step('type description', () =>
294				page.type(
295					'[data-test=transaction-create-description-input]',
296					'versionless-proof-payment',
297					{ redact: false },
298				),
299			);
300			await probe('[data-test=transaction-create-submit-payment]');
301			await step('click submit-payment', () =>
302				page.click('[data-test=transaction-create-submit-payment]', { timeoutMs: 6_000 }),
303			);
304			await delay(1_800);
305			// Feed / filter
306			await probe('[data-test=sidenav-home]');
307			await step('click sidenav-home', () =>
308				page.click('[data-test=sidenav-home]', { timeoutMs: 6_000 }),
309			);
310			await probe('[data-test=nav-public-tab]');
311			await step('click nav-public-tab', () =>
312				page.click('[data-test=nav-public-tab]', { timeoutMs: 6_000 }),
313			);
314			await step('click nav-contacts-tab', () =>
315				page.click('[data-test=nav-contacts-tab]', { timeoutMs: 6_000 }),
316			);
317			await step('click nav-personal-tab', () =>
318				page.click('[data-test=nav-personal-tab]', { timeoutMs: 6_000 }),
319			);
320			await probe('[data-test=transaction-list-filter-amount-range-button]');
321			await probe('[data-test=transaction-list-filter-date-range-button]');
322			await step('click filter-amount-range', () =>
323				page.click('[data-test=transaction-list-filter-amount-range-button]', { timeoutMs: 6_000 }),
324			);
325			await delay(600);
326			// Notifications
327			await probe('[data-test=sidenav-notifications]');
328			await step('click sidenav-notifications', () =>
329				page.click('[data-test=sidenav-notifications]', { timeoutMs: 6_000 }),
330			);
331			await delay(1_200);
332			await context.receipt.capture('calibration-complete');
333		});
334		try {
335			const result = await runBoxes({
336				root: staticRoot,
337				boxes: [
338					{
339						file: join(staticRoot, 'versionless-runtime.box.ts'),
340						relativeFile: 'versionless-runtime.box.ts',
341						exportName: 'default',
342						box: definition,
343					},
344				],
345				receiptDir,
346				assertionTimeoutMs: 8_000,
347				fileSystem: witnessNodeFileSystem,
348				browser: host.browser,
349				headless: true,
350			});
351			status = result.status;
352			failure = result.boxes[0]?.error?.message ?? '';
353			receiptPath = result.receiptPath;
354		} finally {
355			await staticServer.close();
356			await backend.close();
357		}
358		process.stdout.write(
359			`${canonicalize({
360				lane,
361				status,
362				failure,
363				staticOrigin: servedOrigin,
364				backendOrigin: backend.origin,
365				steps,
366				probes,
367				requests: bucketRequests(host.requestOutcomes(), servedOrigin, backend.origin),
368				page: receiptPath === '' ? null : pageSummary(receiptPath),
369			})}\n`,
370		);
371	}
372	
373	export async function main(args = process.argv.slice(2)): Promise<void> {
374		const lane = args[0];
375		if (lane !== 'baseline' && lane !== 'migrated')
376			throw new Error('cypress-rwa calibration requires a lane: baseline or migrated');
377		await calibrateCypressRwaLane(lane);
378	}
379	
380	if (basename(process.argv[1] ?? '') === 'react-cypress-rwa-calibrate-run.ts')
381		main().catch((error: unknown) => {
382			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
383			process.exitCode = 1;
384		});
