26	import { sha256 } from '../../../core/src/receipts/canonicalize.ts';
27	
28	export type ServiceWorkerTelemetry = {
29		state: 'ready' | 'timeout';
30		registration: {
31			scriptPath: string | null;
32			scope: string | null;
33			installing: string | null;
34			waiting: string | null;
35			active: string | null;
36		};
37		controller: string | null;
38		cacheNames: string[];
39		cacheEntries: Array<{ name: string; paths: string[] }>;
40		workerEvents: Array<
41			| { kind: 'registration'; scopePath: string }
42			| { kind: 'version'; scriptPath: string; status: string; runningStatus: string }
43			| {
44					kind: 'error';
45					message: string;
46					sourcePath: string;
47					lineNumber: number;
48					columnNumber: number;
49			  }
50		>;
51	};
52	
53	export type WitnessTransportRequest = {
54		protocol: string;
55		host: string;
56		pathname: string;
57		search: string;
58		method: string;
59		resourceType: string;
60	};
61	
62	export type WitnessTransportDecision =
63		| { action: 'continue' }
64		| { action: 'fulfill'; status: number; contentType: string; body: Buffer };
65	
66	export type ServiceWorkerObserverFinalization = {
67		state: 'target-closed';
68		detach: 'owned-detach-complete';
69		pageClose: 'owned-page-close-complete';
70		workerEvents: ServiceWorkerTelemetry['workerEvents'];
71	};
72	
73	export type WitnessDifferentialEvent = {
74		sequence: number;
75		timestampMs: number;
76		source: 'browser' | 'context-route' | 'manifest' | 'static-server' | 'worker' | 'teardown';
77		phase: string;
78		urlPath: string | null;
79		detail: Record<string, boolean | number | string | null>;
80	};
81	
82	/** Document scroll extents and current offset, read from the live page. */
83	export type WitnessViewportScroll = {
84		scrollHeight: number;
85		clientHeight: number;
86		scrollY: number;
87	};
88	
89	/**
90	 * One request outcome as the page itself reported it, recorded synchronously in
91	 * the same event dispatch the linked Witness runtime records from.
92	 *
93	 * The runtime's own network record resolves each request's response
94	 * asynchronously, which is fine for a receipt written after the page closes but
95	 * useless for a question asked while the journey is still running. This ledger
96	 * exists so that "did this page also fetch that path successfully?" can be
97	 * answered against exactly the set of events the runtime's failed-request count
98	 * was computed from, with no window in which one has seen an event and the
99	 * other has not.
100	 */
101	export type WitnessObservedRequestOutcome = {
102		url: string;
103		method: string;
104		outcome: 'finished' | 'failed';
105		/** Response status for a finished request; null when the browser reported none. */
106		status: number | null;
107		/** The browser's own failure reason for a failed request; null otherwise. */
108		reason: string | null;
109	};
110	
111	/**
112	 * One rendered-appearance measurement to take from the live page: an element,
113	 * and the exact CSS properties whose resolved values are wanted. Nothing about
114	 * the stylesheet is read — these are the values the browser actually resolved
115	 * for a laid-out element, which is the only thing a reader of a styling claim
116	 * cares about.
117	 */
118	export type WitnessRenderedStyleProbe = {
119		label: string;
120		selector: string;
121		properties: readonly string[];
122	};
123	
124	/** The measurement itself, including the element's laid-out box in CSS pixels. */
125	export type WitnessRenderedStyle = {
126		label: string;
127		selector: string;
128		width: number;
129		height: number;
130		properties: Record<string, string>;
131	};
132	
133	/**
134	 * One grouped-text reading to take from the live page: the containers that make
135	 * up the groups, what names each group, and which elements inside a group are
136	 * its items.
137	 *
138	 * This is the reading counterpart of {@link WitnessRenderedStyleProbe}, and it
139	 * exists for the same reason. An application whose state lives in a store
140	 * renders that state as ordered lists — a kanban board, a grouped table, a
141	 * navigation tree — and the only way to record what the store settled to is to
142	 * read what the browser laid out. Assertions still go through `expect.page.*`;
143	 * this produces the evidence those assertions are about.
144	 */
145	export type WitnessGroupedTextProbe = {
146		/** Selector matching every group container, read in document order. */
147		group: string;
148		/** Selector, resolved inside a group, for the element that names it. */
149		name: string;
150		/**
151		 * When set, the group's name is this attribute of the name element rather
152		 * than its text — for a container whose visible label is interleaved with
153		 * other text, the attribute is the stable identity.
154		 */
155		nameAttribute?: string;
156		/** Selector, resolved inside a group, matching its items in document order. */
157		item: string;
158	};
159	
160	/** One group as the page rendered it: its name, and its items in order. */
161	export type WitnessGroupedText = { name: string; items: string[] };
162	
163	/**
164	 * One file-input surface an application declares, and the only way a file ever
165	 * reaches a page under this host.
166	 *
167	 * The declaration is the whole mechanism: it names the input the file is loaded
168	 * into and the fixture that is loaded into it, and the host will load that
169	 * fixture and nothing else. `fixturePath` is repository-relative on purpose —
170	 * it is copied verbatim into the evidence, and a host-specific absolute path has
171	 * no business in a published receipt. The absolute location it is read from is
172	 * the caller's declared root, which is never recorded.
173	 */
174	export type WitnessFileInputSurface = {
175		/** How the journey asks for this surface. Unique within an application. */
176		label: string;
177		selector: string;
178		/** Repository-relative path of the fixture handed to the page. */
179		fixturePath: string;
180	};
181	
182	/** The declared surfaces plus the absolute root the paths resolve against. */
183	export type WitnessFileInputDeclaration = {
184		/** Absolute directory the declared fixture paths resolve against. Never recorded. */
185		root: string;
186		surfaces: readonly WitnessFileInputSurface[];
187	};
188	
189	/** One load as it happened, recorded from the exact bytes handed to the page. */
190	export type WitnessLoadedFileInput = WitnessFileInputSurface & {
191		fileName: string;
192		bytes: number;
193		sha256: string;
194	};
195	
196	/** One download as the browser wrote it, read back rather than counted. */
197	export type WitnessCapturedDownload = {
198		suggestedFilename: string;
199		bytes: number;
200		sha256: string;
201	};
202	
203	/**
204	 * One key an object store holds, and how the store held it.
205	 *
206	 * The rendered form is always a string because that is what a receipt can carry
207	 * and compare, and `kind` is what keeps that rendering honest: a store keyed by
208	 * an auto-incrementing integer and a store keyed by the decimal text of that
209	 * integer are different stores, and a bare string list could not tell a reader
210	 * which one it was looking at.
211	 */
212	export type WitnessIndexedDbKey = { kind: 'string' | 'number'; key: string };
213	
214	/**
215	 * One object store, named with the metadata that explains its keys — never its
216	 * values. `keyPath` and `autoIncrement` are the store's own declaration of where
217	 * its keys come from, which is exactly what a reader needs to interpret the
218	 * list below and is not application data.
219	 */
220	export type WitnessIndexedDbObjectStore = {
221		name: string;
222		keyPath: string | string[] | null;
223		autoIncrement: boolean;
224		keys: WitnessIndexedDbKey[];
225	};
226	
227	/** One database the origin holds, at the version the reader observed it. */
228	export type WitnessIndexedDbDatabase = {
229		name: string;
230		version: number;
231		stores: WitnessIndexedDbObjectStore[];
232	};
233	
234	/**
235	 * Everything this reader is willing to say about an origin's IndexedDB.
236	 *
237	 * The state name is the discipline, stated in the evidence rather than only in
238	 * this comment: keys are read and values are not. An application that keeps a
239	 * person's tasks, notes or translations in IndexedDB has put their data there,
240	 * and a receipt that recorded it would be publishing that data. What a
241	 * persistence claim actually needs is which databases exist, which stores are in
242	 * them and which keys those stores hold — every one of which is a fact about
243	 * the application's own schema rather than about anybody's content.
244	 */
245	export type WitnessIndexedDbKeyInventory = {
246		state: 'read-keys-only';
247		databases: WitnessIndexedDbDatabase[];
248	};
249	
250	/**
251	 * The reader itself, exported as a self-contained function because that is the
252	 * only form in which the page can run it and a test can too: the host hands
253	 * this exact function to the browser, so what a test exercises in process is
254	 * the same source the live page evaluates rather than a second implementation
255	 * written to agree with it.
256	 *
257	 * It refuses rather than coerces in three places, and each refusal is a
258	 * measurement. An origin whose IndexedDB cannot be enumerated is not an origin
259	 * with no databases. A database that has to be CREATED to be read did not exist
260	 * to be read. And a key that is neither a string nor a finite number — a Date, a
261	 * binary key, a compound array key — has a shape this record cannot carry, so it
262	 * says so instead of flattening it into text that would read as a key the store
263	 * does not have.
264	 */
265	export async function readWitnessIndexedDbKeys(): Promise<WitnessIndexedDbKeyInventory> {
266		const factory = globalThis.indexedDB as IDBFactory | undefined;
267		if (factory === undefined || typeof factory.databases !== 'function')
268			throw new Error('Witness IndexedDB key reader found no enumerable IndexedDB');
269		const settled = async <Value>(pending: IDBRequest<Value>): Promise<Value> =>
270			await new Promise<Value>((resolve, reject) => {
271				pending.onsuccess = (): void => resolve(pending.result);
272				pending.onerror = (): void =>
273					reject(new Error('Witness IndexedDB key reader could not read a store'));
274			});
275		const renderKey = (key: IDBValidKey): WitnessIndexedDbKey => {
276			if (typeof key === 'string') return { kind: 'string', key };
277			if (typeof key === 'number' && Number.isFinite(key))
278				return { kind: 'number', key: String(key) };
279			throw new Error('Witness IndexedDB key reader refuses a key it cannot record faithfully');
280		};
281		const names = (await factory.databases())
282			.map((entry) => entry.name)
283			.filter((name): name is string => typeof name === 'string' && name.length > 0)
284			.sort();
285		const databases: WitnessIndexedDbDatabase[] = [];
286		for (const name of names) {
287			const opened = await new Promise<IDBDatabase>((resolve, reject) => {
288				const pending = factory.open(name);
289				pending.onupgradeneeded = (): void =>
290					reject(
291						new Error('Witness IndexedDB key reader refuses to create a database it reads'),
292					);
293				pending.onsuccess = (): void => resolve(pending.result);
294				pending.onerror = (): void =>
295					reject(new Error('Witness IndexedDB key reader could not open a database'));
296			});
297			const storeNames = Array.from(opened.objectStoreNames).sort();
298			const stores: WitnessIndexedDbObjectStore[] = [];
299			if (storeNames.length !== 0) {
300				const transaction = opened.transaction(storeNames, 'readonly');
301				for (const storeName of storeNames) {
302					const store = transaction.objectStore(storeName);
303					const keys = (await settled(store.getAllKeys())).map(renderKey);
304					// Ordered by UTF-16 code unit rather than by `localeCompare`.
305						// The first spelling of this sort used `localeCompare` and was
306						// wrong twice over: it asks the browser's collator, so the order
307						// depends on an ICU locale nobody declared, and it does not agree
308						// with the order the receipt schemas require — every one of them
309						// checks a published key list against `[...values].sort()`, which
310						// is code-unit order. Super Productivity's own store is where the
311						// disagreement is visible: the collator puts
312						// `SUP_P_DEFAULT_TASK_ATTACHMENT_STATE` before
313						// `SUP_P_DEFAULT_TASKS_STATE` and `SUP_PROJECT_META_LIST` after
314						// both, and code-unit order puts all three the other way round, so
315						// a reading taken through the collator fails the schema that
316						// receives it. Comparing with `<` is exactly what the default sort
317						// does, which is the point.
318						keys.sort((left, right) => {
319							const leftKey = `${left.kind}\0${left.key}`;
320							const rightKey = `${right.kind}\0${right.key}`;
321							return leftKey < rightKey ? -1 : leftKey > rightKey ? 1 : 0;
322						});
323					stores.push({
324						name: storeName,
325						keyPath: store.keyPath,
326						autoIncrement: store.autoIncrement,
327						keys,
328					});
329				}
330			}
331			databases.push({ name, version: opened.version, stores });
332			opened.close();
333		}
334		return { state: 'read-keys-only', databases };
335	}
