337	/**
338	 * The string keys of one named store, for a persistence claim whose store is
339	 * string-keyed and says so.
340	 *
341	 * It resolves the store by database and store name and refuses everything else:
342	 * a database or store that is absent, and a key the store held as a number
343	 * where the caller declared strings. A caller that quietly dropped the numeric
344	 * keys would be publishing a shorter list than the store holds.
345	 */
346	export function witnessIndexedDbStringKeys(
347		inventory: WitnessIndexedDbKeyInventory,
348		databaseName: string,
349		storeName: string,
350	): string[] {
351		const database = inventory.databases.find((candidate) => candidate.name === databaseName);
352		if (database === undefined)
353			throw new Error(`Witness IndexedDB key reading found no database: ${databaseName}`);
354		const store = database.stores.find((candidate) => candidate.name === storeName);
355		if (store === undefined)
356			throw new Error(`Witness IndexedDB key reading found no object store: ${storeName}`);
357		if (store.keys.some((key) => key.kind !== 'string'))
358			throw new Error(`Witness IndexedDB object store is not string-keyed: ${storeName}`);
359		return store.keys.map((key) => key.key);
360	}
