391	/**
392	 * The declared surfaces, checked as a declaration rather than trusted as one: a
393	 * surface with no label or selector, a duplicated label, or a fixture path that
394	 * is absolute or climbs out of the declared root is refused here rather than
395	 * being discovered in the evidence.
396	 */
397	export function validateWitnessFileInputDeclaration(
398		declaration: WitnessFileInputDeclaration,
399	): WitnessFileInputDeclaration {
400		if (!isAbsolute(declaration.root))
401			throw new Error('Witness file-input declaration needs an absolute fixture root');
402		if (declaration.surfaces.length === 0)
403			throw new Error('Witness file-input declaration names no surface');
404		const labels = new Set<string>();
405		for (const surface of declaration.surfaces) {
406			const relative = normalize(surface.fixturePath);
407			if (
408				surface.label.length === 0 ||
409				surface.selector.length === 0 ||
410				surface.fixturePath.length === 0 ||
411				isAbsolute(surface.fixturePath) ||
412				relative.startsWith('..')
413			)
414				throw new Error(`Witness file-input surface is malformed: ${surface.label}`);
415			if (labels.has(surface.label))
416				throw new Error(`Witness file-input surface is declared twice: ${surface.label}`);
417			labels.add(surface.label);
418		}
419		return declaration;
420	}
