533	export function validateWitnessTransportDecision(
534		decision: WitnessTransportDecision,
535	): WitnessTransportDecision {
536		if (decision.action === 'continue') return decision;
537		if (
538			!Number.isInteger(decision.status) ||
539			decision.status < 200 ||
540			decision.status > 599 ||
541			decision.contentType.length === 0 ||
542			decision.contentType.length > 128 ||
543			decision.body.length > MAX_TRANSPORT_BODY_BYTES
544		)
545			throw new Error('Witness transport fulfillment exceeds its fixed boundary');
546		return decision;
547	}
