563	async function observeServiceWorkers(
564		cdp: CDPSession,
565		page: Page,
566		workerEvents: ServiceWorkerTelemetry['workerEvents'],
567		diagnosticEvent?: (event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>) => void,
568	): Promise<{
569		finalize(): Promise<void>;
570		readback(): ServiceWorkerObserverFinalization | null;
571	}> {
572		let state: 'attached' | 'finalizing' | 'detached' | 'target-closed' = 'attached';
573		const observerState = (): typeof state => state;
574		let finalization: ServiceWorkerObserverFinalization | null = null;
575		const onRegistrationUpdated = (event: unknown): void => {
576			const registrations = (event as { registrations?: Array<{ scopeURL?: string }> })
577				.registrations;
578			for (const registration of registrations ?? []) {
579				diagnosticEvent?.({
580					source: 'worker',
581					phase: 'registration',
582					urlPath: parseURL(registration.scopeURL ?? '').pathname || '',
583					detail: {},
584				});
585				workerEvents.push({
586					kind: 'registration',
587					scopePath: parseURL(registration.scopeURL ?? '').pathname || '',
588				});
589			}
590		};
591		const onVersionUpdated = (event: unknown): void => {
592			const versions = (
593				event as {
594					versions?: Array<{
595						scriptURL?: string;
596						status?: string;
597						runningStatus?: string;
598					}>;
599				}
600			).versions;
601			for (const version of versions ?? []) {
602				diagnosticEvent?.({
603					source: 'worker',
604					phase: 'version',
605					urlPath: parseURL(version.scriptURL ?? '').pathname || '',
606					detail: {
607						status: version.status ?? 'unknown',
608						runningStatus: version.runningStatus ?? 'unknown',
609					},
610				});
611				workerEvents.push({
612					kind: 'version',
613					scriptPath: parseURL(version.scriptURL ?? '').pathname || '',
614					status: version.status ?? 'unknown',
615					runningStatus: version.runningStatus ?? 'unknown',
616				});
617			}
618		};
619		const onWorkerError = (event: unknown): void => {
620			const nested = (event as { errorMessage?: unknown }).errorMessage;
621			const report =
622				nested !== null && typeof nested === 'object'
623					? (nested as Record<string, unknown>)
624					: (event as Record<string, unknown>);
625			workerEvents.push({
626				kind: 'error',
627				message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
628				sourcePath:
629					typeof report.sourceURL === 'string'
630						? parseURL(report.sourceURL).pathname || ''
631						: '',
632				lineNumber: typeof report.lineNumber === 'number' ? report.lineNumber : 0,
633				columnNumber: typeof report.columnNumber === 'number' ? report.columnNumber : 0,
634			});
635			diagnosticEvent?.({
636				source: 'worker',
637				phase: 'error',
638				urlPath:
639					typeof report.sourceURL === 'string'
640						? parseURL(report.sourceURL).pathname || ''
641						: '',
642				detail: {
643					message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
644				},
645			});
646		};
647		const onTargetClosed = (): void => {
648			if (state !== 'detached')
649				throw new Error(`Witness service-worker observer target closed while ${state}`);
650			state = 'target-closed';
651		};
652		cdp.on('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
653		cdp.on('ServiceWorker.workerVersionUpdated', onVersionUpdated);
654		cdp.on('ServiceWorker.workerErrorReported', onWorkerError);
655		page.on('close', onTargetClosed);
656		await cdp.send('ServiceWorker.enable');
657		return {
658			finalize: async () => {
659				if (state !== 'attached')
660					throw new Error(`Witness service-worker observer duplicate finalization: ${state}`);
661				if (page.isClosed())
662					throw new Error(
663						'Witness service-worker observer target closed before finalization',
664					);
665				state = 'finalizing';
666				diagnosticEvent?.({ source: 'teardown', phase: 'freeze', urlPath: null, detail: {} });
667				const snapshot = Object.freeze(
668					structuredClone(workerEvents).sort((left, right) =>
669						JSON.stringify(left).localeCompare(JSON.stringify(right)),
670					),
671				);
672				cdp.off('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
673				cdp.off('ServiceWorker.workerVersionUpdated', onVersionUpdated);
674				cdp.off('ServiceWorker.workerErrorReported', onWorkerError);
675				await cdp.detach();
676				state = 'detached';
677				diagnosticEvent?.({ source: 'teardown', phase: 'detached', urlPath: null, detail: {} });
678				await page.close();
679				page.off('close', onTargetClosed);
680				if (observerState() !== 'target-closed')
681					throw new Error('Witness service-worker observer missed the owned page close');
682				finalization = {
683					state: 'target-closed',
684					detach: 'owned-detach-complete',
685					pageClose: 'owned-page-close-complete',
686					workerEvents: [...snapshot],
687				};
688				diagnosticEvent?.({
689					source: 'teardown',
690					phase: 'target-closed',
691					urlPath: null,
692					detail: {},
693				});
694			},
695			readback: () => (finalization === null ? null : structuredClone(finalization)),
696		};
697	}
