711	function modifiers(mask: number): string[] {
712		return [
713			...(mask & 1 ? ['Alt'] : []),
714			...(mask & 2 ? ['Control'] : []),
715			...(mask & 4 ? ['Meta'] : []),
716			...(mask & 8 ? ['Shift'] : []),
717		];
718	}
719	
720	function keyWithModifiers(key: string, mask: number): string {
721		return [...modifiers(mask), key].join('+');
722	}
