724	async function requestRecord(request: Request, startedAt: number): Promise<BrowserNetworkRequest> {
725		const response = await request.response();
726		return {
727			url: request.url(),
728			method: request.method(),
729			resourceType: request.resourceType(),
730			startTimeMs: startedAt,
731			responseTimeMs: response === null ? null : Date.now(),
732			endTimeMs: Date.now(),
733			durationMs: Date.now() - startedAt,
734			status: response?.status() ?? null,
735			mimeType: response?.headers()['content-type'] ?? null,
736			encodedDataLength: null,
737			failedReason: request.failure()?.errorText ?? null,
738			initiatorType: null,
739		};
740	}
