742	async function waitForScrollableChange(
743		page: Page,
744		target: string | null,
745		deltaX: number,
746		deltaY: number,
747		timeoutMs: number,
748	): Promise<void> {
749		const expression =
750			target === null
751				? '({ x: window.scrollX, y: window.scrollY })'
752				: `(() => { const element = document.querySelector(${JSON.stringify(target)}); return element === null ? null : { x: element.scrollLeft, y: element.scrollTop }; })()`;
753		const before = (await page.evaluate(expression)) as { x: number; y: number } | null;
754		if (target !== null) await page.locator(target).first().hover({ timeout: timeoutMs });
755		await page.mouse.wheel(deltaX, deltaY);
756		await page.waitForFunction(
757			({ stateExpression, previous }) => {
758				const current = globalThis.eval(stateExpression) as { x: number; y: number } | null;
759				return (
760					current !== null &&
761					(previous === null || current.x !== previous.x || current.y !== previous.y)
762				);
763			},
764			{ stateExpression: expression, previous: before },
765			{ timeout: timeoutMs },
766		);
767	}
