769	function adaptPage(
770		page: Page,
771		closePage: () => Promise<void>,
772		navigationWaitUntil: 'domcontentloaded' | 'networkidle',
773		requestOutcomes: WitnessObservedRequestOutcome[],
774	): WitnessBrowserPage {
775		const consoleListeners: Array<(message: BrowserConsoleMessage) => void> = [];
776		const pageErrorListeners: Array<(error: BrowserPageError) => void> = [];
777		const failureListeners: Array<(failure: BrowserRequestFailure) => void> = [];
778		const requestListeners: Array<(request: BrowserNetworkRequest) => void> = [];
779		const navigationListeners: Array<(url: string) => void> = [];
780		const requestStarts = new WeakMap<Request, number>();
781		/**
782		 * Response status captured the moment the headers arrive, so a finished
783		 * outcome can be recorded below without awaiting anything.
784		 */
785		const responseStatus = new WeakMap<Request, number>();
786		page.on('console', (message) => {
787			for (const listener of consoleListeners)
788				listener({ level: message.type(), text: message.text() });
789		});
790		page.on('pageerror', (error) => {
791			for (const listener of pageErrorListeners) listener({ message: error.message });
792		});
793		page.on('request', (request) => requestStarts.set(request, Date.now()));
794		page.on('response', (response) => responseStatus.set(response.request(), response.status()));
795		page.on('requestfailed', (request) => {
796			const failure = {
797				url: request.url(),
798				method: request.method(),
799				reason: request.failure()?.errorText ?? null,
800			};
801			// Recorded before the listeners run, so nothing reading this ledger can
802			// observe a failure the linked Witness record has not also observed.
803			requestOutcomes.push({ ...failure, outcome: 'failed', status: null });
804			for (const listener of failureListeners) listener(failure);
805			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
806				for (const listener of requestListeners) listener(record);
807			});
808		});
809		page.on('requestfinished', (request) => {
810			requestOutcomes.push({
811				url: request.url(),
812				method: request.method(),
813				outcome: 'finished',
814				status: responseStatus.get(request) ?? null,
815				reason: null,
816			});
817			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
818				for (const listener of requestListeners) listener(record);
819			});
820		});
821		page.on('framenavigated', (frame) => {
822			if (frame === page.mainFrame())
823				for (const listener of navigationListeners) listener(frame.url());
824		});
