1	import { describe, expect, it } from 'vitest';
2	import {
3		REACT_CYPRESS_RWA_SOURCE,
4		WITNESS_JOURNEY_PLACEHOLDER_RULE,
5		WITNESS_LIVE_BACKEND_SERVED_RULE,
6		WITNESS_LOOPBACK_BACKEND_RULE,
7		WITNESS_REACT_CYPRESS_RWA_ACTOR,
8		WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY,
9		WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS,
10		WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS,
11		WITNESS_REACT_CYPRESS_RWA_ROUTES,
12		WITNESS_REACT_CYPRESS_RWA_SCHEMA,
13		type WitnessLoopbackBackendInventory,
14		type WitnessReactCypressRwaReceipt,
15		type WitnessReactCypressRwaRun,
16		parseWitnessReactCypressRwaReceipt,
17		witnessReactCypressRwaBehaviorDigest,
18		witnessReactCypressRwaDigest,
19		witnessReactCypressRwaRawDigest,
20	} from '../src/index.ts';
21	
22	const digest = (seed: string): string => seed.padStart(64, '0').slice(0, 64);
23	
24	function backendInventory(): WitnessLoopbackBackendInventory {
25		const observed = [
26			{ method: 'GET', path: '/checkAuth', requests: 2, statuses: [200, 401] },
27			{ method: 'POST', path: '/login', requests: 1, statuses: [200] },
28			{ method: 'POST', path: '/transactions', requests: 1, statuses: [200] },
29		];
30		return {
31			policy: 'live-first-party-loopback-backend',
32			backend: 'live-loopback',
33			rule: WITNESS_LOOPBACK_BACKEND_RULE,
34			category: WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY.map((entry) => ({ ...entry })),
35			observed,
36			absent: [],
37			outsideCategory: [],
38			admitted: observed.reduce((sum, entry) => sum + entry.requests, 0),
39			successfulNonLoopback: 0,
40		};
41	}
42	
43	function makeRun(lane: 'baseline' | 'migrated', pass: 1 | 2): WitnessReactCypressRwaRun {
44		// Byte inventory is lane-specific on purpose; everything else is shared, so
45		// the lane-independent behavior digest is identical and the pass-twice raw
46		// digest is stable within a lane.
47		const bytes = lane === 'baseline' ? digest('ba5e') : digest('m1g7a7ed');
48		const run: WitnessReactCypressRwaRun = {
49			app: 'cypress-realworld-app',
50			framework: 'react',
51			lane,
52			pass,
53			result: 'pass',
54			interactions: [
55				{ kind: 'click', selector: '[data-test=signup]' },
56				{ kind: 'type', selector: '[data-test=signup-username]' },
57			],
58			assertions: ['sign up', 'money movement', 'clean page'],
59			routes: [...WITNESS_REACT_CYPRESS_RWA_ROUTES],
60			trackedEvents: ['click', 'input', 'keydown'],
61			witnessRecord: {
62				interactions: [{ kind: 'click', selector: '[data-test=signup]' }],
63				navigationPaths: [...WITNESS_REACT_CYPRESS_RWA_ROUTES],
64				trackedEventCounts: { click: 12, input: 8, keydown: 8 },
65				consoleErrors: 0,
66				pageErrors: 0,
67				failedRequests: 0,
68			},
69			cleanPage: true,
70			servedStatic: {
71				transport: 'isolated-bounded-loopback-production-static',
72				documentFallback: 'index-only',
73				missingAssets: '404',
74				traversal: 'rejected',
75				inventory: { files: 84, beforeSha256: bytes, afterSha256: bytes },
76				application: { path: 'index.html', beforeSha256: bytes, afterSha256: bytes },
77				byteIdentical: true,
78				hmrControls: false,
79				liveBackend: {
80					backend: 'live-loopback',
81					byteInventoryScope: 'frontend-spa-dist',
82					rule: WITNESS_LIVE_BACKEND_SERVED_RULE,
83				},
84			},
85			loopbackBackend: backendInventory(),
86			placeholders: WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS,
87			successfulNonLoopback: 0,
88			semanticDigest: '',
89			behaviorDigest: '',
90		};
91		run.semanticDigest = witnessReactCypressRwaRawDigest(run);
92		run.behaviorDigest = witnessReactCypressRwaBehaviorDigest(run);
93		return run;
94	}
95	
96	function makeReceipt(): WitnessReactCypressRwaReceipt {
97		const runs = [
98			makeRun('baseline', 1),
99			makeRun('baseline', 2),
100			makeRun('migrated', 1),
101			makeRun('migrated', 2),
102		];
103		const receipt: WitnessReactCypressRwaReceipt = {
104			schemaVersion: WITNESS_REACT_CYPRESS_RWA_SCHEMA,
105			result: 'pass',
106			fixture: 'react-cypress-rwa',
107			application: 'cypress-realworld-app',
108			framework: 'react',
109			source: { ...REACT_CYPRESS_RWA_SOURCE },
110			provenance: {},
111			canonicalReceipt: { path: 'evidence/x.json', canonicalDigest: digest('c'), sha256: digest('d') },
112			runs,
113			mutation: {
114				failure: 'witness-semantic-assertion',
115				intendedFailure: true,
116				lane: 'migrated',
117				seam: 'App bootstrap root',
118				path: 'src/index.tsx',
119				offset: 42,
